	FROM dbo.f_SplitString(@transid, ',')
	WHERE val <> ''
	OPTION (maxrecursion 0)

	--zzzbettrans
	;WITH CTE AS
	(
		SELECT ROW_NUMBER() OVER (PARTITION BY b.transid ORDER BY b.transid) AS Rn
		FROM dbo.zzzbettrans b WITH (NOLOCK)
			INNER JOIN #tmp t on t.val = b.transid
		WHERE b.matchid = 36050775 AND VoidingHistoryId = 9671
	)
	DELETE FROM CTE
	WHERE Rn <> 1

	--TicketVoiding_VoidedTransaction
	;WITH CTE2 AS
	(
		SELECT ROW_NUMBER() OVER (PARTITION BY tv.transid ORDER BY transid) AS Rn
		FROM dbo.TicketVoiding_VoidedTransaction tv WITH (NOLOCK)
			INNER JOIN #tmp t on t.val = tv.transid
		WHERE tv.matchid = 36050775
	)
	DELETE FROM CTE2
	WHERE Rn <> 1

	DROP TABLE #tmp
END